// Buffered reports the number of committed-but-unflushed rows.
func (inst *LedgerStore) Buffered() int { return inst.buffered }

// Flush drains the buffered rows to ClickHouse (Arrow IPC, ADR-0089
// pivot). Rows are durable when Flush returns, engine permitting. On
// insert failure the transferred records are retained and the next
// Flush ships them — Flush is retryable; DiscardPending drops them
// instead. An open (uncommitted) entity frame makes Flush error.
func (inst *LedgerStore) Flush(ctx context.Context) (n int, err error) {
	// Ordered flush (ADR-0112 SD5): make the dimension facts this batch
	// references durable before the payload insert, so a referencing row is
	// never durable ahead of its descriptor. On failure nothing is
	// transferred yet — the buffered rows stay and the next Flush retries.
	//
	// This runs BEFORE the nothing-to-do return: a Begin that stamped and
	// then rolled back, or a caller flushing a store whose own rows all
	// went elsewhere, still leaves dimension rows buffered in the stampers,
	// and skipping them here would strand descriptors no later Flush of
	// this store is obliged to ship. Flushing an empty stamper is free.
	if !inst.cfg.BestEffortStampFlush {
		for _, s := range inst.stampers {
			if _, ferr := s.Flush(ctx); ferr != nil {
				err = eh.Errorf("ordered flush of stampers: %w", ferr)
				return
			}
		}
	}
	if inst.buffered == 0 && len(inst.pending) == 0 {
		return
	}
	records, err := lowlevel.InEntityLedgerTableTransferRecords(inst.dml, nil)
	if err != nil {
		err = eh.Errorf("transfer records: %w", err)
		return
	}
	records = append(inst.pending, records...)
	inst.pending = nil
	// One batch id per insert attempt (ADR-0295 §SD6): the executor stamps
	// it, an observing executor reports it, the write observer is told it.
	batch := recordstore.NewBatchId()
	bctx := recordstore.WithBatchId(ctx, batch)
	if len(records) > 0 {
		err = inst.exec.InsertArrow(bctx, inst.writeTable(), records)
		if err != nil {
			inst.pending = records
			err = eh.Errorf("insert into %s: %w", inst.writeTable(), err)
			return
		}
	}
	for _, rec := range records {
		rec.Release()
	}
	n = inst.buffered
	inst.buffered = 0
	for k := range inst.dirty {
		inst.notifyFlush(k) // durable now — release the views' dirty-window pins
	}
	clear(inst.dirty) // flushed — ClickHouse now serves the written state
	if len(inst.written) > 0 {
		inst.cfg.WriteObserver.Durable(bctx, batch, inst.takeWritten())
	}
	return
}

// DrainCanonical writes the rows buffered since the last Flush to w as
// canonical wire items (ADR-0210), one per entity in commit order, as a
// CBOR sequence, and discards them: nothing is inserted, and the store
// is as DiscardPending leaves it. n is the number of items written. A
// store opened for nothing else needs no executor (ADR-0325 §SD2).
func (inst *LedgerStore) DrainCanonical(w io.Writer) (n int, err error) {
	records, err := lowlevel.InEntityLedgerTableTransferRecords(inst.dml, nil)
	if err != nil {
		err = eh.Errorf("transfer records: %w", err)
		return
	}
	records = append(inst.pending, records...)
	inst.pending = nil
	defer func() {
		for _, rec := range records {
			rec.Release()
		}
		inst.buffered = 0
		for k := range inst.dirty {
			inst.notifyWrite(k, nil)
		}
		clear(inst.dirty)
		if len(inst.written) > 0 {
			inst.cfg.WriteObserver.Discarded(inst.takeWritten())
		}
	}()
	acc := lowlevel.NewReadAccessLedgerTable()
	enc, err := lowlevel.NewCanonWireEncoderLedgerTable(acc, lowlevel.CanonWireOrdinalTaggerLedgerTable{})
	if err != nil {
		err = eh.Errorf("canonical wire encoder: %w", err)
		return
	}
	for _, rec := range records {
		if err = acc.LoadFromRecord(rec); err != nil {
			err = eh.Errorf("load the buffered rows: %w", err)
			return
		}
		err = enc.EncodeAll(w)
		n += int(rec.NumRows())
		acc.Release()
		if err != nil {
			err = eh.Errorf("encode the buffered rows: %w", err)
			return
		}
	}
	return
}

// CanonicalItem is the canonical wire item (ADR-0210) of ent as this store
// would write it: the entity re-entered into a scratch store with no
// executor and drained, so a row read back from the server has the item
// the writer chained. The scratch store carries no stampers and no
// observer; what a stamper adds to a stored row is not in the item. An
// entity with a tombstone lifecycle, or whose row carried hand-written
// contributions, is not reproducible from its decoded form: the first is
// refused, the second drains without them. Safe for concurrent use.
func (inst *LedgerStore) CanonicalItem(ent *LedgerEntity) (item []byte, err error) {
	if ent == nil {
		err = eh.Errorf("canonical item: nil entity")
		return
	}
	inst.scratchMu.Lock()
	defer inst.scratchMu.Unlock()
	if inst.scratch == nil {
		inst.scratch = NewLedgerStore(nil, nil, LedgerStoreConfig{})
	}
	b := inst.scratch.beginCtx(context.Background(), ent.ID, ent.Ord, false)
	if ent.LedgerMeta.Has {
		b.AddLedgerMeta(ent.LedgerMeta.Val)
	}
	if ent.EvidenceChain.Has {
		b.AddEvidenceChain(ent.EvidenceChain.Val)
	}
	if ent.EvidenceWrittenBy.Has {
		b.AddEvidenceWrittenBy(ent.EvidenceWrittenBy.Val)
	}
	if err = b.Commit(); err != nil {
		inst.scratch.DiscardPending()
		err = eh.Errorf("canonical item: %w", err)
		return
	}
	var buf bytes.Buffer
	n, err := inst.scratch.DrainCanonical(&buf)
	if err != nil {
		err = eh.Errorf("canonical item: %w", err)
		return
	}
	if n != 1 {
		err = eh.Errorf("canonical item: the entity drained as %d items, not one", n)
		return
	}
	item = buf.Bytes()
	return
}

// writtenByOf is the written-by component of a row committed under ctx
// (ADR-0327 (proposed) §SD6): the call identity's origin and claims, the
// batch and the attestation on ctx, as evidence.IdentityFrom reads them.
func (inst *LedgerStore) writtenByOf(ctx context.Context) (row EvidenceWrittenBy) {
	id := evidence.IdentityFrom(ctx)
	row = EvidenceWrittenBy{Kind: EvidenceWrittenByKind, Instance: id.Instance, OriginBy: id.OriginBy.String(), PrincipalBy: id.PrincipalBy}
	if id.Run != "" {
		row.Run = option.Some(id.Run)
	}
	if id.App != "" {
		row.App = option.Some(id.App)
	}
	if id.Principal != "" {
		row.Principal = option.Some(id.Principal)
	}
	if id.Purpose != "" {
		row.Purpose = option.Some(id.Purpose)
	}
	if id.Correlation != "" {
		row.Correlation = option.Some(id.Correlation)
	}
	if id.Batch != "" {
		row.Batch = option.Some(id.Batch)
	}
	return
}

// AppendChained commits ent as the next row of its scope's chain (ADR-0327
// (proposed) §SD2, law L31): the ordinal after head's, the chain component's
// Prev, Digest and Scheme set by the store — the mark and the commitments
// are the caller's — and the digest over the row's canonical item with Prev
// and Digest at zero, chained to head's digest (the seed for an empty
// scope). The written-by component is the context's, whatever ent carried.
// The row is buffered as Commit buffers; Flush makes it durable. ent is
// updated in place and digest is what its chain component now records.
func (inst *LedgerStore) AppendChained(ctx context.Context, head evidence.Head, ent *LedgerEntity) (digest string, err error) {
	if inst.cfg.Scheme.IsZero() {
		err = eh.Errorf("append chained: the store has no scheme (LedgerStoreConfig.Scheme)")
		return
	}
	if ent == nil {
		err = eh.Errorf("append chained: nil entity")
		return
	}
	ent.Ord = head.Ordinal + 1
	ch := ent.EvidenceChain.Val
	ch.Kind, ch.Prev, ch.Digest, ch.Scheme = EvidenceChainKind, head.Ordinal, "", inst.cfg.Scheme.Name()
	if ch.Mark == "" {
		ch.Mark = evidence.MarkNone.String()
	}
	ent.EvidenceChain = option.Some(ch)
	ent.EvidenceWrittenBy = option.Some(inst.writtenByOf(ctx))
	item, err := inst.chainItem(ent)
	if err != nil {
		err = eh.Errorf("append chained: %w", err)
		return
	}
	digest = inst.cfg.Scheme.ChainDigest(head.Digest, item)
	ch.Digest = digest
	ent.EvidenceChain = option.Some(ch)
	b := inst.beginCtx(ctx, ent.ID, ent.Ord, false)
	if ent.LedgerMeta.Has {
		b.AddLedgerMeta(ent.LedgerMeta.Val)
	}
	if ent.EvidenceChain.Has {
		b.AddEvidenceChain(ent.EvidenceChain.Val)
	}
	if ent.EvidenceWrittenBy.Has {
		b.AddEvidenceWrittenBy(ent.EvidenceWrittenBy.Val)
	}
	if err = b.Commit(); err != nil {
		digest = ""
		err = eh.Errorf("append chained: %w", err)
	}
	return
}

// chainItem is the canonical item of ent with the chain's Prev and Digest
// at zero: what its chain digest is over.
func (inst *LedgerStore) chainItem(ent *LedgerEntity) (item []byte, err error) {
	c := *ent
	if c.EvidenceChain.Has {
		ch := c.EvidenceChain.Val
		ch.Prev, ch.Digest = 0, ""
		c.EvidenceChain = option.Some(ch)
	}
	return inst.CanonicalItem(&c)
}

// Head is the chain head of scope: the latest row's ordinal and digest.
// found is false for a scope with no row; a scope whose latest row carries
// no chain component is an error.
func (inst *LedgerStore) Head(ctx context.Context, scope uint64) (h evidence.Head, found bool, err error) {
	ent, found, err := inst.Latest(ctx, scope)
	if err != nil || !found {
		return
	}
	if !ent.EvidenceChain.Has {
		err = eh.Errorf("head: the latest row of the scope carries no chain component")
		return
	}
	h = evidence.Head{Ordinal: ent.Ord, Digest: ent.EvidenceChain.Val.Digest}
	return
}

// ChainRows reads the rows of scope from an ordinal on, in order, as the
// laws read them.
func (inst *LedgerStore) ChainRows(ctx context.Context, scope uint64, from uint64) (rows []evidence.RowI, err error) {
	for ent, e := range inst.Replay(ctx, scope, from, recordstore.ReplayOptsU64{}) {
		if e != nil {
			err = e
			return
		}
		rows = append(rows, inst.ChainRow(ent))
	}
	return
}

// VerifyChain is law L31 over scope from seed: the first ordinal that
// breaks the chain and why, or zero when it holds.
func (inst *LedgerStore) VerifyChain(ctx context.Context, scope uint64, seed string) (broken uint64, why evidence.BreakE, err error) {
	rows, err := inst.ChainRows(ctx, scope, 0)
	if err != nil {
		return
	}
	return evidence.Verify(inst.cfg.Scheme, seed, rows)
}

// ChainRow is ent as the laws read it. It implements evidence.HeadRowI,
// answering a head for a keep-marked row that records one. Openings and
// vault items come from the vault; without one every commitment reads as
// absent content.
func (inst *LedgerStore) ChainRow(ent *LedgerEntity) evidence.RowI {
	return &ledgerChainRow{store: inst, ent: ent}
}

type ledgerChainRow struct {
	store *LedgerStore
	ent   *LedgerEntity
	// openings are the vault's, by component; vaultItem is the canonical
	// item of a component's vault row without its opening.
	openings  map[string][]byte
	vaultItem func(component string) ([]byte, error)
}

var _ evidence.HeadRowI = (*ledgerChainRow)(nil)

func (inst *ledgerChainRow) chain() EvidenceChain           { return inst.ent.EvidenceChain.Val }
func (inst *ledgerChainRow) Ordinal() uint64                { return inst.ent.Ord }
func (inst *ledgerChainRow) Prev() uint64                   { return inst.chain().Prev }
func (inst *ledgerChainRow) Digest() string                 { return inst.chain().Digest }
func (inst *ledgerChainRow) CanonicalItem() ([]byte, error) { return inst.store.chainItem(inst.ent) }
func (inst *ledgerChainRow) Mark() evidence.Mark {
	ch := inst.chain()
	m, _ := evidence.ParseMark(ch.Mark)
	return evidence.Mark{Mark: m, Target: ch.MarkTarget, Component: ch.MarkComponent.Val}
}
func (inst *ledgerChainRow) Commitments() (cs []evidence.Commitment) {
	ch := inst.chain()
	for i, component := range ch.CommitComponents {
		c := evidence.Commitment{Component: component}
		if i < len(ch.Commitments) {
			c.Commitment = ch.Commitments[i]
		}
		if o, ok := inst.openings[component]; ok {
			c.Opening, c.Present = o, true
		}
		cs = append(cs, c)
	}
	return
}
func (inst *ledgerChainRow) VaultItem(component string) ([]byte, error) {
	if inst.vaultItem == nil {
		return nil, eh.Errorf("vault item: the row was read without its vault")
	}
	return inst.vaultItem(component)
}
func (inst *ledgerChainRow) Head() (ordinal uint64, digest string, ok bool) {
	ch := inst.chain()
	if ch.Mark != evidence.MarkKeep.String() || !ch.HeadDigest.Has {
		return
	}
	return ch.MarkTarget, ch.HeadDigest.Val, true
}

// LedgerVaulted is the store a host runs under the profile's vault (ADR-0327
// (proposed) §SD4): a ledger that never holds content and a vault with one
// row per (scope, ordinal, component), each with the opening the ledger's
// commitment opens under. Append writes the content first, then the ledger
// row with one commitment per component; reads join the two and hand the
// laws the openings; erasure is per component, a rewrite of the vault's
// part. Safe for concurrent use as far as its stores are: Append, Flush and
// Close are the single writer's; the reads take the stores' executors.
type LedgerVaulted struct {
	ledger *LedgerStore
	vault  *LedgerVaultStore
}

// NewLedgerVaulted is the ledger and its vault; the scheme is the ledger's.
func NewLedgerVaulted(ledger *LedgerStore, vault *LedgerVaultStore) *LedgerVaulted {
	return &LedgerVaulted{ledger: ledger, vault: vault}
}

// Ledger and Vault are the stores underneath.
func (inst *LedgerVaulted) Ledger() *LedgerStore     { return inst.ledger }
func (inst *LedgerVaulted) Vault() *LedgerVaultStore { return inst.vault }

// LedgerVaultComponents are the kind tags of the vaulted components, the
// names the ledger's commitments and the vault's component column carry.
var LedgerVaultComponents = []string{
	"ledgerNote",
}

// Split prepares content for the row at ordinal: for each content row the
// component it holds names it, the opening is drawn, the commitment to the
// row's canonical item without the opening goes onto ent's chain component,
// and the row gains its opening. A content row must hold exactly one
// vaulted component. ent and content are updated in place.
func (inst *LedgerVaulted) Split(ent *LedgerEntity, ordinal uint64, content []*LedgerVaultEntity) (err error) {
	if inst.ledger.cfg.Scheme.IsZero() {
		err = eh.Errorf("split: the ledger has no scheme (LedgerStoreConfig.Scheme)")
		return
	}
	ch := ent.EvidenceChain.Val
	ch.CommitComponents, ch.Commitments = nil, nil
	for _, v := range content {
		component := ""
		if v.LedgerNote.Has {
			if component != "" {
				err = eh.Errorf("split: a content row holds more than one vaulted component")
				return
			}
			component = "ledgerNote"
		}
		if component == "" {
			err = eh.Errorf("split: a content row holds no vaulted component")
			return
		}
		v.ID, v.Ord = ent.ID, ordinal
		v.LedgerVaultEnvelope.Component = component
		v.EvidenceOpening = option.None[EvidenceOpening]()
		item, e := inst.vault.CanonicalItem(v)
		if e != nil {
			err = eh.Errorf("split: %w", e)
			return
		}
		opening := evidence.NewOpening()
		v.EvidenceOpening = option.Some(EvidenceOpening{Kind: EvidenceOpeningKind, Opening: evidence.OpeningText(opening)})
		ch.CommitComponents = append(ch.CommitComponents, component)
		ch.Commitments = append(ch.Commitments, inst.ledger.cfg.Scheme.Commit(opening, item))
	}
	ent.EvidenceChain = option.Some(ch)
	return
}

// Append is Split, the content rows into the vault, and the ledger row
// through AppendChained, in that order: a ledger row whose content is
// missing reads as erased and breaks law L31 unless the chain explains it,
// while a vault row without its ledger row is dead weight nothing reads.
// Both stores buffer; Flush makes the rows durable, vault first.
func (inst *LedgerVaulted) Append(ctx context.Context, head evidence.Head, ent *LedgerEntity, content []*LedgerVaultEntity) (digest string, err error) {
	if err = inst.Split(ent, head.Ordinal+1, content); err != nil {
		return
	}
	for _, v := range content {
		b := inst.vault.BeginCtx(ctx, v.ID, v.Ord, v.LedgerVaultEnvelope)
		if v.LedgerNote.Has {
			b.AddLedgerNote(v.LedgerNote.Val)
		}
		if v.EvidenceOpening.Has {
			b.AddEvidenceOpening(v.EvidenceOpening.Val)
		}
		if err = b.Commit(); err != nil {
			err = eh.Errorf("append: vault: %w", err)
			return
		}
	}
	return inst.ledger.AppendChained(ctx, head, ent)
}

// Flush makes the buffered rows durable, the vault's before the ledger's.
func (inst *LedgerVaulted) Flush(ctx context.Context) (err error) {
	if _, err = inst.vault.Flush(ctx); err != nil {
		return eh.Errorf("flush: vault: %w", err)
	}
	if _, err = inst.ledger.Flush(ctx); err != nil {
		return eh.Errorf("flush: ledger: %w", err)
	}
	return
}

// Close closes both stores.
func (inst *LedgerVaulted) Close() {
	inst.vault.Close()
	inst.ledger.Close()
}

// Join is the ledger rows as the laws read them with the vault's openings
// and items attached, and the content rows grouped by ordinal. Of several
// vault rows for one (ordinal, component) the last listed stands; the
// laws say whether it opens.
func (inst *LedgerVaulted) Join(ledger []*LedgerEntity, content []*LedgerVaultEntity) (rows []evidence.RowI, byOrdinal map[uint64][]*LedgerVaultEntity) {
	byOrdinal = make(map[uint64][]*LedgerVaultEntity)
	for _, v := range content {
		byOrdinal[v.Ord] = append(byOrdinal[v.Ord], v)
	}
	for _, e := range ledger {
		row := inst.ledger.ChainRow(e).(*ledgerChainRow)
		vaults := make(map[string]*LedgerVaultEntity)
		for _, v := range byOrdinal[e.Ord] {
			if v.ID != e.ID {
				continue
			}
			vaults[v.LedgerVaultEnvelope.Component] = v
		}
		row.openings = make(map[string][]byte, len(vaults))
		for component, v := range vaults {
			if v.EvidenceOpening.Has {
				if o := evidence.OpeningOf(v.EvidenceOpening.Val.Opening); o != nil {
					row.openings[component] = o
				}
			}
		}
		row.vaultItem = func(component string) ([]byte, error) {
			v, ok := vaults[component]
			if !ok {
				return nil, eh.Errorf("vault item: no row for the component")
			}
			c := *v
			c.EvidenceOpening = option.None[EvidenceOpening]()
			return inst.vault.CanonicalItem(&c)
		}
		rows = append(rows, row)
	}
	return
}

// Rows reads scope's rows from an ordinal on, ledger and vault, and joins
// them.
func (inst *LedgerVaulted) Rows(ctx context.Context, scope uint64, from uint64) (rows []evidence.RowI, byOrdinal map[uint64][]*LedgerVaultEntity, err error) {
	var ledger []*LedgerEntity
	for e, er := range inst.ledger.Replay(ctx, scope, from, recordstore.ReplayOptsU64{}) {
		if er != nil {
			err = eh.Errorf("rows: ledger: %w", er)
			return
		}
		ledger = append(ledger, e)
	}
	var content []*LedgerVaultEntity
	for v, er := range inst.vault.Replay(ctx, scope, from, recordstore.ReplayOptsU64{}) {
		if er != nil {
			err = eh.Errorf("rows: vault: %w", er)
			return
		}
		content = append(content, v)
	}
	rows, byOrdinal = inst.Join(ledger, content)
	return
}

// VerifyChain is law L31 over scope from seed, the vault's openings in hand.
func (inst *LedgerVaulted) VerifyChain(ctx context.Context, scope uint64, seed string) (broken uint64, why evidence.BreakE, err error) {
	rows, _, err := inst.Rows(ctx, scope, 0)
	if err != nil {
		return
	}
	return evidence.Verify(inst.ledger.cfg.Scheme, seed, rows)
}

// Erase rewrites the vault rows at ordinals out of the table, all their
// components or only those named: ALTER TABLE … DELETE with
// mutations_sync = 2, so the bytes are gone when it returns, not masked
// for a later merge (ADR-0320 §SD4). The erased mark that explains the
// absence is the writer's to append first (ADR-0327 (proposed) §SD3).
func (inst *LedgerVaulted) Erase(ctx context.Context, scope uint64, ordinals []uint64, components []string) (err error) {
	if len(ordinals) == 0 {
		return
	}
	where := LedgerVaultColKey + " = " + strconv.FormatUint(scope, 10) + " AND " + LedgerVaultColOrder + " IN (" + evidenceOrdinals(ordinals) + ")"
	if len(components) > 0 {
		var names string
		if names, err = evidenceComponentLiterals(components); err != nil {
			return
		}
		where += " AND " + LedgerVaultColComponent + " IN (" + names + ")"
	}
	return inst.mutate(ctx, where)
}

// Destroy rewrites scope's vault rows out of the table but those at keep.
func (inst *LedgerVaulted) Destroy(ctx context.Context, scope uint64, keep []uint64) (err error) {
	where := LedgerVaultColKey + " = " + strconv.FormatUint(scope, 10)
	if len(keep) > 0 {
		where += " AND " + LedgerVaultColOrder + " NOT IN (" + evidenceOrdinals(keep) + ")"
	}
	return inst.mutate(ctx, where)
}

func (inst *LedgerVaulted) mutate(ctx context.Context, where string) (err error) {
	if inst.vault.exec == nil {
		return eh.Errorf("the vault has no executor")
	}
	if err = inst.vault.exec.Exec(ctx, "ALTER TABLE "+inst.vault.writeTable()+" DELETE WHERE "+where+" SETTINGS mutations_sync = 2"); err != nil {
		err = eh.Errorf("erase vault rows: %w", err)
	}
	return
}

// evidenceOrdinals are ordinals as the order column's literals.
func evidenceOrdinals(ordinals []uint64) string {
	parts := make([]string, 0, len(ordinals))
	for _, o := range ordinals {
		parts = append(parts, strconv.FormatUint(o, 10))
	}
	return strings.Join(parts, ", ")
}

// evidenceComponentLiterals are kind tags as string literals; a tag is a
// Go identifier, so anything else is refused rather than quoted.
func evidenceComponentLiterals(components []string) (s string, err error) {
	parts := make([]string, 0, len(components))
	for _, c := range components {
		for _, r := range c {
			if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '_') {
				err = eh.Errorf("a component name is not a kind tag")
				return
			}
		}
		parts = append(parts, "'"+c+"'")
	}
	s = strings.Join(parts, ", ")
	return
}

// FlushIfDue is Flush once cfg.FlushEvery rows are buffered, and a no-op
// before that — or always, when FlushEvery is zero. Call it between
// entities (after Commit): like Flush it errors on an open frame. A
// failure leaves the rows retained exactly as Flush does, so the next
// FlushIfDue or Flush retries them. Flush stays the end-of-run call —
// FlushIfDue leaves up to FlushEvery-1 rows buffered.
func (inst *LedgerStore) FlushIfDue(ctx context.Context) (n int, err error) {
	if inst.cfg.FlushEvery <= 0 || inst.buffered < inst.cfg.FlushEvery {
		return
	}
	return inst.Flush(ctx)
}

// DiscardPending drops every committed-but-unflushed row: records
// retained by a failed Flush, rows still in the DML builder, and an
// open (uncommitted) entity frame. It gives a failed Flush "never
// happened" semantics — ClickHouse state is the truth afterwards.
// Ambient stamps are cleared with the frame they were pushed for —
// including any pushed through Raw() — so an abandoned builder cannot
// leak its stamps onto later entities.
func (inst *LedgerStore) DiscardPending() {
	_ = lowlevel.InEntityLedgerTableRollbackEntity(inst.dml) // no-op error when no frame is open
	inst.dml.ClearMembershipsHighCardRef()                   // an abandoned Begin's stamps must not outlive its frame
	if records, err := lowlevel.InEntityLedgerTableTransferRecords(inst.dml, nil); err == nil {
		for _, rec := range records {
			rec.Release()
		}
	}
	for _, rec := range inst.pending {
		rec.Release()
	}
	inst.pending = nil
	inst.buffered = 0
	for k := range inst.dirty {
		inst.notifyWrite(k, nil) // the cached write never became durable — invalidate
	}
	clear(inst.dirty) // nothing local remains — ClickHouse is the truth
	if len(inst.written) > 0 {
		inst.cfg.WriteObserver.Discarded(inst.takeWritten())
	}
}

// Close discards everything unflushed and releases the store's Arrow
// builder; the store must not be used afterwards. Required for a
// clean shutdown under tracking/checked allocators — the default Go
// allocator needs no Close.
func (inst *LedgerStore) Close() {
	inst.DiscardPending()
	lowlevel.InEntityLedgerTableReleaseBuilder(inst.dml)
	inst.scratchMu.Lock()
	if inst.scratch != nil {
		inst.scratch.Close()
		inst.scratch = nil
	}
	inst.scratchMu.Unlock()
}

// LedgerCacheConfig parameterizes an attached read-through cache view.
type LedgerCacheConfig struct {
	// Capacity is the L1 capacity in entries, not bytes — budget
	// memory as Capacity × the largest expected entity payload. Zero
	// or negative selects the default (1024).
	Capacity int
	// FetchCriteria are the cache's batch-flush thresholds.
	FetchCriteria caching.FetchCriteria
	// FreshnessTTL enables age-based staleness onset (ADR-0100's
	// external-writer staleness story): entries older than this read
	// as stale — strict reads miss and queue a refetch, accept-stale
	// reads keep serving. Zero disables (staleness stays signal-only).
	FreshnessTTL time.Duration
	// NegativeTTL enables absent-key marking: keys a clean fetch did
	// not return are treated as absent for this long — misses on them
	// neither queue nor suspend work items, so replay loops over keys
	// that do not exist terminate. Zero disables.
	NegativeTTL time.Duration
}

// LedgerCache is the batched read-through, write-through KV view over a
// LedgerStore (ADR-0100 SD5): misses queue under work items and flush
// as one IN (…) lookup, and local writes populate the view at Commit —
// pinned until the store's Flush makes them durable — so reads after
// writes hit immediately. Admission is version-gated on the entity's
// Order value: a raced refetch of an older row bounces off. Only
// EXTERNAL writers can leave the view stale; they need a caller-
// provided signal: MarkStale / Invalidate / InvalidateAll (a freshness
// TTL option exists on the underlying cache). Raw() commits and
// discarded writes invalidate instead of populating. Like the store
// it wraps, a view is single-goroutine. W is the work-item type (use
// struct{} when the suspend/replay machinery is not needed).
type LedgerCache[W comparable] struct {
	st    *LedgerStore
	cfg   LedgerCacheConfig
	cache *caching.ReadThroughCache[uint64, *LedgerEntity, W]
}

// NewLedgerCache attaches a read-through, write-through cache view to st,
// registering its write-through and flush hooks with the store. Views
// attach for the store's lifetime — there is no detach.
func NewLedgerCache[W comparable](st *LedgerStore, cfg LedgerCacheConfig) (inst *LedgerCache[W]) {
	if cfg.Capacity <= 0 {
		cfg.Capacity = 1024
	}
	inst = &LedgerCache[W]{st: st, cfg: cfg}
	inst.rebuild()
	// The hooks close over the view, not the cache instance, keeping
	// them correct if the cache is ever swapped out.
	st.onWrite = append(st.onWrite, func(k uint64, ent *LedgerEntity) {
		if ent == nil {
			inst.cache.Delete(k) // not materializable or discarded: invalidate
			return
		}
		inst.cache.AddItem(k, ent) // version-gated write-through
		inst.cache.Pin(k)          // dirty-window latch, released by Flush
	})
	st.onFlush = append(st.onFlush, func(k uint64) { inst.cache.Unpin(k) })
	return
}

func (inst *LedgerCache[W]) rebuild() {
	opts := []caching.CacheOption[uint64, *LedgerEntity, W]{
		// Admission mirrors the table's newest-row-per-key semantics:
		// the Order value is the entity's monotonic version. The int64
		// reinterpretation preserves the per-key order as long as one
		// key's values share their top bit — which a single writer
		// stream per key (the SD2 contract) gives by construction.
		caching.WithVersioning[uint64, *LedgerEntity, W](func(e *LedgerEntity) int64 { return int64(e.Ord) }),
	}
	if inst.cfg.FreshnessTTL > 0 {
		opts = append(opts, caching.WithFreshnessTTL[uint64, *LedgerEntity, W](inst.cfg.FreshnessTTL))
	}
	if inst.cfg.NegativeTTL > 0 {
		opts = append(opts, caching.WithNegativeCaching[uint64, *LedgerEntity, W](inst.cfg.NegativeTTL))
	}
	inst.cache = caching.NewReadThroughCache[uint64, *LedgerEntity, W](inst.cfg.Capacity, &ledgerFetcher{st: inst.st}, inst.cfg.FetchCriteria, opts...)
}

// Get retrieves an entity by Key through the cache; local writes are
// visible immediately (write-through). A miss queues the key for the
// next batch fetch (the caching suspend/replay contract). A miss can
// also mean the batched fetch errored (misses swallow fetch errors;
// the circuit breaker backs off) — GetFetch surfaces the error
// instead, and the store's Latest stays the authoritative check. The
// returned entity is shared with the cache: treat it as immutable.
func (inst *LedgerCache[W]) Get(key uint64) (ent *LedgerEntity, found bool) {
	return inst.cache.Get(key)
}

// GetFetch is the single-lookup read: the cached entity when present,
// otherwise one immediate batched point fetch — fetch errors surface
// instead of reading as misses, so found=false with err=nil is the
// authoritative absent. A key in the dirty write window that the cache
// could not answer is an error rather than a stale row (see below).
// Prefer Get plus the work-item protocol when batching lookups across a
// frame; the initial miss here also queues the key, so a later batch
// fetch may include it redundantly (harmless).
func (inst *LedgerCache[W]) GetFetch(ctx context.Context, key uint64) (ent *LedgerEntity, found bool, err error) {
	ent, found = inst.cache.Get(key)
	if found {
		return
	}
	if _, d := inst.st.dirty[key]; d {
		// The key was written locally and is not yet flushed, so ClickHouse
		// still serves the PRE-write row — and the cache miss above means
		// there is no local answer either (a Raw() commit, or a discarded
		// write, invalidates the entry rather than materializing it; an
		// ordinary commit is pinned and would have hit). Returning the
		// pre-write row would be stale, and found=false would assert the
		// authoritative absent this method promises and cannot stand behind
		// here — so say so instead. Flush first, or read through Get plus the
		// work-item protocol, whose fetcher drops dirty keys as a MISS, which
		// queues a refetch rather than claiming absence.
		err = eh.Errorf("get-fetch: key is in the dirty write window — written locally and not yet flushed, and the write was not materializable into the cache; Flush before reading it back")
		return
	}
	ents, err := inst.st.queryEntities(ctx, inst.st.fetchLatestSQL([]uint64{key}))
	if err != nil {
		err = eh.Errorf("get-fetch: %w", err)
		return
	}
	for _, e := range ents {
		if e.ID != key {
			continue
		}
		ent = e
		found = true
		inst.cache.AddItem(key, e)
	}
	return
}

// WorkItem marks the current work item for the cache's miss bookkeeping.
func (inst *LedgerCache[W]) WorkItem(w W) iter.Seq[functional.NilIteratorValueType] {
	return inst.cache.WorkItem(w)
}

// IterateReadyWorkItems flushes the queued keys when the fetch criteria
// are met and replays the work items that had misses.
func (inst *LedgerCache[W]) IterateReadyWorkItems(ctx context.Context) iter.Seq[W] {
	return inst.cache.IterateReadyWorkItems(ctx)
}

// IterateRestWorkItems forces a fetch of all queued keys and replays
// the pending work items.
func (inst *LedgerCache[W]) IterateRestWorkItems(ctx context.Context) iter.Seq[W] {
	return inst.cache.IterateRestWorkItems(ctx)
}

// AdvanceEpoch advances the cache's pinning epoch — call once per
// frame / batch so untouched L1 entries become evictable.
func (inst *LedgerCache[W]) AdvanceEpoch() {
	inst.cache.AdvanceEpoch()
}

// MarkStale flags the key's cached entry as stale — the external-writer
// signal: the next strict read misses and queues a refetch, while
// accept-stale reads keep serving the old value until it lands.
func (inst *LedgerCache[W]) MarkStale(key uint64) {
	inst.cache.MarkAsStale(key)
}

// MarkStaleIfOlder is the version-carrying external-writer signal:
// it stales the cached entry only if its Order is below order, so a
// redundant signal for a version the view already holds is free —
// the natural sink for an invalidation stream carrying (key, Order).
func (inst *LedgerCache[W]) MarkStaleIfOlder(key uint64, order uint64) {
	inst.cache.MarkAsStaleIfOlder(key, int64(order))
}

// Invalidate drops the key's cached entry (L1 and stash).
func (inst *LedgerCache[W]) Invalidate(key uint64) {
	inst.cache.Delete(key)
}

// InvalidateAll drops every cached entry — the bulk external-writer
// signal (e.g. after an import). In-flight miss bookkeeping (queued
// keys, pending work items) and the dirty-window pins are dropped
// with it: call between frames, with no suspended work and no
// unflushed local writes (the fetcher's dirty-guard keeps pre-write
// rows out of the cleared cache until the next Flush, at the cost of
// misses on those keys).
func (inst *LedgerCache[W]) InvalidateAll() {
	inst.cache.Clear()
}

// fetchLatestSQL is the batched newest-row-per-key point lookup shared
// by the cache fetcher and GetFetch.
func (inst *LedgerStore) fetchLatestSQL(keys []uint64) string {
	var sb strings.Builder
	sb.WriteString("SELECT * FROM ")
	sb.WriteString(inst.readTable())
	sb.WriteString(" WHERE " + LedgerColKey + " IN (")
	for i, k := range keys {
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(ledgerKeyLiteral(k))
	}
	sb.WriteString(") ORDER BY " + LedgerColOrder + " DESC LIMIT 1 BY " + LedgerColKey)
	sb.WriteString(ledgerArrowOutputSettings)
	return sb.String()
}

// ledgerFetcher implements caching.ItemFetcherI for attached cache views —
// an unexported shim so the fetch plumbing stays off the store's
// public method set.
type ledgerFetcher struct{ st *LedgerStore }

var _ caching.ItemFetcherI[uint64, *LedgerEntity] = (*ledgerFetcher)(nil)

// DeterminePartition implements caching.ItemFetcherI. Single partition
// in v1 (one table, one server).
func (inst *ledgerFetcher) DeterminePartition(key uint64) uint64 { return 0 }

// FetchItemSinglePartition implements caching.ItemFetcherI: one batched
// point lookup per fetch. Duplicate versions collapse newest-first.
// Dirty keys (written locally, not yet flushed) are fetched but not
// cached. With write-through the version gate already rejects the
// pre-write row while the newer entry is resident; this guard is the
// remaining defense for dirty keys the views could NOT materialize
// (Raw commits, discarded writes) and for InvalidateAll inside a
// dirty window, where the cache is cold and the gate has nothing to
// compare against.
func (inst *ledgerFetcher) FetchItemSinglePartition(ctx context.Context, partition uint64, keys []uint64, target caching.ItemTargetI[uint64, *LedgerEntity]) (err error) {
	ents, err := inst.st.queryEntities(ctx, inst.st.fetchLatestSQL(keys))
	if err != nil {
		return
	}
	for _, ent := range ents {
		if _, d := inst.st.dirty[ent.ID]; d {
			continue
		}
		target.AddItem(ent.ID, ent)
	}
	return
}

// Baked ADR-0066 Filter artefacts: rows carrying a conforming
// component. Generated from Plan ⋈ IR; membership ids are literals.
const (
	ledgerScanLedgerMetaFilter        = "has(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9002) AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9002) = 1"
	ledgerScanEvidenceChainFilter     = "hasAll(\"tv:symbol:lr:lr:u64:1247:::0::data\", [9101, 9104, 9105]) AND hasAll(\"tv:u64Array:lr:lr:u64:1247:::0::data\", [9102, 9106]) AND has(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9103) AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9101) = 1 AND countEqual(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9102) = 1 AND if(has(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9102), \"tv:u64Array:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9102), arrayCumSum(\"tv:u64Array:lrcard:lrcard:u64:4E:::0::data\"))], 0) = 1 AND countEqual(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9103) = 1 AND if(has(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9103), \"tv:stringArray:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9103), arrayCumSum(\"tv:stringArray:lrcard:lrcard:u64:4E:::0::data\"))], 0) = 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9104) = 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9105) = 1 AND countEqual(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9106) = 1 AND if(has(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9106), \"tv:u64Array:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9106), arrayCumSum(\"tv:u64Array:lrcard:lrcard:u64:4E:::0::data\"))], 0) = 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9107) <= 1 AND countEqual(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9108) <= 1 AND if(has(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9108), \"tv:stringArray:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9108), arrayCumSum(\"tv:stringArray:lrcard:lrcard:u64:4E:::0::data\"))], 0) <= 1 AND countEqual(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9109) <= 1 AND countEqual(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9110) <= 1"
	ledgerScanEvidenceWrittenByFilter = "hasAll(\"tv:symbol:lr:lr:u64:1247:::0::data\", [9201, 9205, 9207]) AND has(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9204) AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9201) = 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9202) <= 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9203) <= 1 AND countEqual(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9204) = 1 AND if(has(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9204), \"tv:u64Array:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:u64Array:lr:lr:u64:1247:::0::data\", 9204), arrayCumSum(\"tv:u64Array:lrcard:lrcard:u64:4E:::0::data\"))], 0) = 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9205) = 1 AND countEqual(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9206) <= 1 AND if(has(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9206), \"tv:stringArray:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9206), arrayCumSum(\"tv:stringArray:lrcard:lrcard:u64:4E:::0::data\"))], 0) <= 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9207) = 1 AND countEqual(\"tv:symbol:lr:lr:u64:1247:::0::data\", 9208) <= 1 AND countEqual(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9209) <= 1 AND if(has(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9209), \"tv:stringArray:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9209), arrayCumSum(\"tv:stringArray:lrcard:lrcard:u64:4E:::0::data\"))], 0) <= 1 AND countEqual(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9210) <= 1 AND if(has(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9210), \"tv:stringArray:len:len:u64:4D:::0::data\"[arrayFirstIndex(cum -> cum >= indexOf(\"tv:stringArray:lr:lr:u64:1247:::0::data\", 9210), arrayCumSum(\"tv:stringArray:lrcard:lrcard:u64:4E:::0::data\"))], 0) <= 1"
)

// ScanLedgerMeta iterates the entities whose rows carry a conforming LedgerMeta
// component, ordered by (Order, Key) — or by opts.OrderBy's envelope
// column, opts.Descending reversing either — so entities sharing an Order
// still come out in a fixed sequence. Rows that tie on BOTH (the same
// key written twice at the same Order) are not ordered against each
// other by this clause; the table keeps newest-per-key, so which of
// them survives is the engine's choice, not the scan's.
// opts.KeyPrefix is refused (recordstore.ErrKeyPrefixNumericKey):
// this store's key is not a string.
// opts.ExtraPredicate (trusted raw SQL over the physical columns —
// never untrusted input) further restricts the scan; opts.Limit
// caps the row count. The Filter artefact uses ClickHouse
// built-ins only, so this is a single SELECT — no helper UDFs, no
// multi-statement script (the ExecutorI contract). The sequence is
// single-use; ctx must stay valid until iteration completes; an
// error ends it as a final (nil, err) pair. Scans see only flushed
// rows.
func (inst *LedgerStore) ScanLedgerMeta(ctx context.Context, opts recordstore.ScanOpts) iter.Seq2[*LedgerEntity, error] {
	if opts.KeyPrefix != "" {
		return recordstore.RefuseKeyPrefix[*LedgerEntity]()
	}
	order, err := ledgerOrderBy(opts)
	if err != nil {
		return recordstore.FailScan[*LedgerEntity](err)
	}
	where := ledgerScanLedgerMetaFilter
	if opts.ExtraPredicate != "" {
		where = "(" + where + ") AND (" + opts.ExtraPredicate + ")"
	}
	sql := "SELECT * FROM " + inst.readTable() +
		" WHERE " + where + order
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += ledgerArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// ScanEvidenceChain iterates the entities whose rows carry a conforming EvidenceChain
// component, ordered by (Order, Key) — or by opts.OrderBy's envelope
// column, opts.Descending reversing either — so entities sharing an Order
// still come out in a fixed sequence. Rows that tie on BOTH (the same
// key written twice at the same Order) are not ordered against each
// other by this clause; the table keeps newest-per-key, so which of
// them survives is the engine's choice, not the scan's.
// opts.KeyPrefix is refused (recordstore.ErrKeyPrefixNumericKey):
// this store's key is not a string.
